    public static readonly IReadOnlyList<DoctrineSkill> All = new DoctrineSkill[]
    {
        new("lust01", DoctrineBranch.Lust, 1, "", "찬미의 미소\u001FBlessed Smile", "교주의 미소 한 번에 사람들이 성스러운 욕망을 찬양합니다.\u001FOne smile from the leader and people praise holy desire.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 5f), Cult(StatId.Doctrine, -2f) }, GiftedSpecial.Chance("Proselytize", 4)),
        new("lust02", DoctrineBranch.Lust, 2, "", "밤의 성회\u001FHoly Night Gatherings", "온 마을이 축복하는 밤의 집회가 신도를 하나로 묶습니다.\u001FNight gatherings the whole town blesses bind the followers together.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 3f), Personal(PersonalStatId.Lust, 5f), Personal(PersonalStatId.Health, -2f) }),
        new("lust03", DoctrineBranch.Lust, 3, "", "성스러운 언변\u001FSacred Tongue", "달콤한 말은 이 세상에서 가장 존경받는 설교가 됩니다.\u001FSweet words become the most respected sermons in this world.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 3f), Cult(StatId.Doctrine, -2f) }, GiftedSpecial.Chance("Preach", 7)),
        new("lust04", DoctrineBranch.Lust, 4, "", "쾌락의 계명\u001FCommandment of Pleasure", "욕망은 의무이며 금욕이야말로 죄라고 가르칩니다.\u001FYou teach that desire is a duty and abstinence the true sin.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 5f), Personal(PersonalStatId.Integrity, -5f), Cult(StatId.LeaderFaith, -2f) }),
        new("lust05", DoctrineBranch.Lust, 5, "", "거룩한 황홀\u001FHoly Ecstasy", "의식마다 신도들이 황홀 속에서 신성에 다가갑니다.\u001FWith every ritual, followers draw nearer the divine through ecstasy.", 5, 0, new StatModifier[] { Cult(StatId.Followers, 4f), Personal(PersonalStatId.Health, -1f) }, GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("lust06a", DoctrineBranch.Lust, 6, "A", "열애의 서약\u001FVow of Passion", "교주에게 바친 열애의 서약은 가장 명예로운 맹세입니다.\u001FA passionate vow to the leader is the most honored oath of all.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 8f), Cult(StatId.LeaderFaith, -3f) }, GiftedSpecial.Chance("Desire", 5)),
        new("lust06b", DoctrineBranch.Lust, 6, "B", "무희의 성제\u001FDancers' Holy Festival", "무희들의 축제는 온 도시가 찬미하는 성스러운 무대입니다.\u001FThe dancers' festival is a sacred stage the whole city adores.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 7f), Cult(StatId.Followers, 5f), Cult(StatId.Doctrine, -3f) }),
        new("lust07a", DoctrineBranch.Lust, 7, "A", "육체의 대성전\u001FGrand Temple of the Flesh", "해마다 순례자들이 쾌락의 대성전으로 몰려듭니다.\u001FEvery year, pilgrims flock to the grand temple of pleasure.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 8f), Personal(PersonalStatId.Health, -4f) }, GiftedSpecial.Yearly(StatId.Followers, 3), GiftedSpecial.Yearly(StatId.Offerings, 10)),
        new("lust07b", DoctrineBranch.Lust, 7, "B", "관능의 성가대\u001FSensual Choir", "성가대의 관능적인 노래가 해마다 새 신도를 부릅니다.\u001FEvery year, the choir's sensual song calls new followers.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, -3f) }, GiftedSpecial.Yearly(StatId.Followers, 2), GiftedSpecial.Chance("Preach", 12)),
        new("lust08a", DoctrineBranch.Lust, 8, "A", "사모하는 권력자들\u001FAdoring Powers", "권력자들조차 교주의 매력을 영광으로 여기며 무릎 꿇습니다.\u001FEven the powerful count it an honor to kneel before the leader's charm.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 9f), Cult(StatId.Offerings, 6f), Cult(StatId.LeaderFaith, -4f) }),
        new("lust08b", DoctrineBranch.Lust, 8, "B", "축복의 연서\u001FBlessed Love Letters", "교주의 연서 한 통은 받는 이에게 최고의 영예입니다.\u001FA single love letter from the leader is the highest honor a follower can receive.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 8f), Personal(PersonalStatId.Health, -3f) }, GiftedSpecial.Chance("Proselytize", 6)),
        new("lust09a", DoctrineBranch.Lust, 9, "A", "지고의 의식\u001FSupreme Rites", "가장 대담한 의식일수록 세상은 더 큰 경외를 바칩니다.\u001FThe bolder the rite, the greater the awe the world offers.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 9f), Cult(StatId.FollowerFaith, 6f), Cult(StatId.Doctrine, -6f) }, GiftedSpecial.Chance("CultPray", 5)),
        new("lust09b", DoctrineBranch.Lust, 9, "B", "찬란한 설교\u001FDazzling Sermons", "관능이 넘치는 설교에 사람들이 영화처럼 빠져듭니다.\u001FPeople are swept into your sensual sermons like a feature film.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 7f), Cult(StatId.Followers, 9f), Cult(StatId.LeaderFaith, -4f) }),
        new("lust10a", DoctrineBranch.Lust, 10, "A", "쾌락의 군주\u001FLord of Pleasure", "교주는 온 세상이 숭배하는 쾌락 그 자체가 되었습니다.\u001FThe leader has become pleasure itself, worshipped by the whole world.", 2, 0, new StatModifier[] { Cult(StatId.Followers, 14f), Cult(StatId.Reputation, 10f), Cult(StatId.FollowerFaith, 6f), Personal(PersonalStatId.Health, -6f) }, GiftedSpecial.Yearly(PersonalStatId.Health, 3)),
        new("lust10b", DoctrineBranch.Lust, 10, "B", "뮤즈의 교단\u001FCult of the Muse", "예술가들이 욕망을 찬미하는 걸작을 교단에 바칩니다.\u001FArtists offer the cult masterpieces glorifying desire.", 2, 0, new StatModifier[] { Cult(StatId.Followers, 13f), Cult(StatId.Reputation, 10f), Cult(StatId.FollowerFaith, 6f), Cult(StatId.Doctrine, -6f) }, GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("greed01", DoctrineBranch.Greed, 1, "", "황금 바구니\u001FThe Golden Basket", "헌금 바구니가 돌 때마다 사람들은 더 많이 내는 것을 자랑합니다.\u001FEvery time the basket goes round, people boast of giving more.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 5f), Cult(StatId.Reputation, 2f), Cult(StatId.Doctrine, -1f) }),
        new("greed02", DoctrineBranch.Greed, 2, "", "영광의 십일조\u001FGlorious Tithe", "해마다 신도들이 수입의 십분의 일을 자랑스럽게 바칩니다.\u001FEvery year, followers proudly give a tenth of their income.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 2f), Cult(StatId.FollowerFaith, -2f) }, GiftedSpecial.Yearly(StatId.Offerings, 10)),
        new("greed03", DoctrineBranch.Greed, 3, "", "축복의 시세\u001FThe Market Price of Blessing", "값을 치른 축복만이 진짜라고 가르치니 모두가 수긍합니다.\u001FYou teach that only paid blessings are real, and everyone agrees.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 5f), Cult(StatId.Doctrine, -2f) }, GiftedSpecial.Chance("Desire", 5)),
        new("greed04", DoctrineBranch.Greed, 4, "", "신성한 사업\u001FSacred Enterprise", "교단의 이름으로 상점과 공장을 열어 부를 찬양합니다.\u001FYou open shops and factories in the cult's name to glorify wealth.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 6f), Personal(PersonalStatId.Wealth, 3f), Personal(PersonalStatId.Integrity, -3f), Cult(StatId.FollowerFaith, -3f) }),
        new("greed05", DoctrineBranch.Greed, 5, "", "황금 제단\u001FThe Golden Altar", "제단의 금붙이가 늘어날수록 세상은 교단을 더 우러러봅니다.\u001FThe more gold adorns the altar, the more the world looks up to the cult.", 5, 0, new StatModifier[] { Cult(StatId.Offerings, 4f), Cult(StatId.FollowerFaith, -1f) }, GiftedSpecial.Yearly(StatId.LeaderFaith, 3)),
        new("greed06a", DoctrineBranch.Greed, 6, "A", "부적 판매\u001FTalisman Sales", "교주의 부적은 성공한 자의 상징으로 불티나게 팔립니다.\u001FThe leader's talismans sell like hotcakes as a mark of success.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 3f), Cult(StatId.Doctrine, -4f) }, GiftedSpecial.Yearly(StatId.Offerings, 20)),
        new("greed06b", DoctrineBranch.Greed, 6, "B", "영리한 상회\u001FThe Shrewd Trading House", "교단 상회는 누구보다 영리하게 버는 곳으로 칭송받습니다.\u001FThe cult's trading house is praised for earning more shrewdly than anyone.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 6f), Cult(StatId.Reputation, 5f), Cult(StatId.FollowerFaith, -2f) }),
        new("greed07a", DoctrineBranch.Greed, 7, "A", "큰손 후원자\u001FBig Patrons", "부자들이 교단 후원을 최고의 명예로 여기며 앞다퉈 나섭니다.\u001FThe wealthy compete to back the cult, counting it their greatest honor.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 9f), Cult(StatId.Authority, 5f), Cult(StatId.LeaderFaith, -3f) }),
        new("greed07b", DoctrineBranch.Greed, 7, "B", "축복의 금고\u001FVault of Blessings", "해마다 신도들의 저축이 교단의 금고를 불려 갑니다.\u001FEvery year, the followers' savings swell the cult's vault.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Wealth, 5f), Cult(StatId.FollowerFaith, -3f) }, GiftedSpecial.Yearly(StatId.Offerings, 15)),
        new("greed08a", DoctrineBranch.Greed, 8, "A", "불어나는 재단\u001FThe Growing Foundation", "돈이 돈을 낳는 재단은 이 세상의 성스러운 기적입니다.\u001FA foundation where money breeds money is this world's holy miracle.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.Offerings, 30), GiftedSpecial.Yearly(StatId.Reputation, 4), GiftedSpecial.Yearly(StatId.Doctrine, -10)),
        new("greed08b", DoctrineBranch.Greed, 8, "B", "황금 무역 조합\u001FGolden Trade Guild", "교단 상인들이 먼 땅까지 이윤의 복음을 전합니다.\u001FThe cult's merchants carry the gospel of profit to distant lands.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 9f), Cult(StatId.Followers, 5f), Cult(StatId.Doctrine, -3f) }),
        new("greed09a", DoctrineBranch.Greed, 9, "A", "면죄의 값\u001FThe Price of Absolution", "헌금만큼 죄가 씻긴다는 선포에 모두가 기꺼이 지갑을 엽니다.\u001FYou proclaim that offerings wash away sin, and all gladly open their purses.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 3f), Personal(PersonalStatId.Integrity, -6f), Cult(StatId.LeaderFaith, -4f) }, GiftedSpecial.Chance("Desire", 8)),
        new("greed09b", DoctrineBranch.Greed, 9, "B", "투자 재단\u001FInvestment Fund", "학생들에게 돈 버는 법을 가르치는 재단이 존경을 받습니다.\u001FA fund that teaches students to make money earns great respect.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 6f), Cult(StatId.LeaderFaith, -4f) }, GiftedSpecial.Yearly(StatId.Reputation, 6), GiftedSpecial.Yearly(StatId.Offerings, 15)),
        new("greed10a", DoctrineBranch.Greed, 10, "A", "황금 교단\u001FThe Golden Cult", "마르지 않는 창고는 신이 교단을 총애한다는 증거입니다.\u001FThe cult's never-empty storehouses prove the gods' favor.", 2, 0, new StatModifier[] { Cult(StatId.Offerings, 17f), Cult(StatId.Reputation, 10f), Personal(PersonalStatId.Wealth, 6f), Cult(StatId.Doctrine, -6f) }, GiftedSpecial.Yearly(StatId.LeaderFaith, 4)),
        new("greed10b", DoctrineBranch.Greed, 10, "B", "번영의 신전\u001FTemple of Prosperity", "쌓아 올린 부가 신전을 찬란하게 빛냅니다.\u001FAmassed wealth makes the temple shine in splendor.", 2, 0, new StatModifier[] { Cult(StatId.Offerings, 13f), Cult(StatId.Reputation, 10f), Personal(PersonalStatId.Wealth, 8f), Cult(StatId.FollowerFaith, -5f) }, GiftedSpecial.Yearly(StatId.LeaderFaith, 4)),
        new("appetite01", DoctrineBranch.Appetite, 1, "", "함께 먹는 성찬\u001FHoly Shared Meal", "배 터지게 함께 먹는 밥이 신도들을 가깝게 합니다.\u001FEating together until bursting brings the followers closer.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 5f), Cult(StatId.Followers, 3f), Personal(PersonalStatId.Health, -2f) }),
        new("appetite02", DoctrineBranch.Appetite, 2, "", "폭식의 날\u001FDay of Feasting", "해마다 열리는 큰 잔치에서 가장 많이 먹은 자가 칭송받습니다.\u001FAt the great yearly feast, whoever eats the most is praised.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 4f), Cult(StatId.Offerings, -2f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 8)),
        new("appetite03", DoctrineBranch.Appetite, 3, "", "포만의 기도\u001FPrayer of Fullness", "배불리 먹게 해 달라는 기도가 가장 경건한 기도가 됩니다.\u001FThe prayer to eat one's fill becomes the most devout of prayers.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 3f), Personal(PersonalStatId.Health, -2f) }, GiftedSpecial.Chance("CultPray", 7)),
        new("appetite04", DoctrineBranch.Appetite, 4, "", "성스러운 부엌\u001FThe Sacred Kitchen", "이웃을 불러 아낌없이 먹이는 부엌이 신성한 곳이 됩니다.\u001FThe kitchen that feeds neighbors without restraint becomes holy ground.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 8f), Cult(StatId.Reputation, 3f), Cult(StatId.Offerings, -4f) }),
        new("appetite05", DoctrineBranch.Appetite, 5, "", "넘치는 식탁\u001FAn Overflowing Table", "식탁이 넘칠수록 마음도, 명성도 넘칩니다.\u001FThe fuller the table, the fuller the heart and the fame.", 5, 0, new StatModifier[] { Cult(StatId.Reputation, 4f), Personal(PersonalStatId.Health, -1f) }, GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("appetite06a", DoctrineBranch.Appetite, 6, "A", "배부른 신도\u001FWell-Fed Followers", "통통하게 살찐 신도는 복받은 자로 존경받습니다.\u001FPlump, well-fed followers are revered as the blessed.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 10f), Cult(StatId.Reputation, 3f), Personal(PersonalStatId.Health, -4f) }),
        new("appetite06b", DoctrineBranch.Appetite, 6, "B", "풍요의 농장\u001FFarm of Abundance", "교단 농장의 수확이 창고를 넘치게 채웁니다.\u001FThe cult farm's harvest fills the storehouse to overflowing.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 6f), Personal(PersonalStatId.Health, -2f) }, GiftedSpecial.Yearly(StatId.Offerings, 10)),
        new("appetite07a", DoctrineBranch.Appetite, 7, "A", "대축제 추수제\u001FGreat Harvest Feast", "가을마다 새 얼굴들이 끝없는 잔치를 찾아옵니다.\u001FEvery autumn, new faces come for the endless feast.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 7f), Cult(StatId.Followers, 5f), Cult(StatId.Offerings, -3f) }, GiftedSpecial.Yearly(StatId.Followers, 3)),
        new("appetite07b", DoctrineBranch.Appetite, 7, "B", "풍작의 경작\u001FBountiful Farming", "함께 땀 흘려 더 많이 거두는 신도들이 하나가 됩니다.\u001FFollowers who sweat together to reap ever more become one.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 7f), Cult(StatId.Followers, 5f), Personal(PersonalStatId.Health, -3f) }),
        new("appetite08a", DoctrineBranch.Appetite, 8, "A", "만찬의 성찬\u001FThe Sacred Supper", "호화로운 만찬 그 자체가 예배가 됩니다.\u001FThe lavish supper itself becomes worship.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 10f), Cult(StatId.Offerings, -4f) }, GiftedSpecial.Chance("Serve", 5)),
        new("appetite08b", DoctrineBranch.Appetite, 8, "B", "곡간 개방\u001FOpen Granaries", "흉년에도 곡간을 열어 모두가 배 터지게 먹게 합니다.\u001FEven in lean years, you open the granaries so all may eat their fill.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 10f), Cult(StatId.Offerings, -4f) }, GiftedSpecial.Chance("Serve", 5)),
        new("appetite09a", DoctrineBranch.Appetite, 9, "A", "탐식의 대제\u001FGrand Festival of Gluttony", "끝없는 탐식의 축제에 온 세상이 열광합니다.\u001FThe whole world goes wild for endless festivals of gluttony.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 10f), Personal(PersonalStatId.Appetite, 10f), Cult(StatId.Reputation, 5f), Personal(PersonalStatId.Health, -8f), Cult(StatId.Offerings, -4f) }),
        new("appetite09b", DoctrineBranch.Appetite, 9, "B", "미식의 제례\u001FRites of Fine Dining", "계절마다 진미를 바치는 제례가 신앙을 깊게 합니다.\u001FSeasonal rites offering delicacies deepen the faith.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, -4f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 15), GiftedSpecial.Chance("CultPray", 8)),
        new("appetite10a", DoctrineBranch.Appetite, 10, "A", "풍요의 왕국\u001FKingdom of Plenty", "교단에서는 누구도 굶지 않고 모두가 마음껏 먹습니다.\u001FNo one in the cult goes hungry; all eat to their heart's content.", 2, 0, new StatModifier[] { Cult(StatId.Reputation, 10f), Cult(StatId.Followers, 7f), Personal(PersonalStatId.Health, -6f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 20), GiftedSpecial.Yearly(StatId.Followers, 3), GiftedSpecial.Yearly(PersonalStatId.Health, 3)),
        new("appetite10b", DoctrineBranch.Appetite, 10, "B", "대지의 어머니\u001FMother Earth", "교단은 굶주린 자를 배불리 먹이는 위대한 어머니가 되었습니다.\u001FThe cult has become a great mother who feasts the hungry.", 2, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 11f), Cult(StatId.Reputation, 12f), Cult(StatId.Followers, 4f), Cult(StatId.Offerings, -6f) }, GiftedSpecial.Yearly(StatId.Followers, 3), GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("ambition01", DoctrineBranch.Ambition, 1, "", "출세의 첫걸음\u001FFirst Step Up", "교단이 첫 직위를 만들자 모두가 오르려 다툽니다.\u001FThe cult creates its first offices, and all compete to climb.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 5f), Cult(StatId.Reputation, 2f), Cult(StatId.FollowerFaith, -1f) }),
