        new("ambition03", DoctrineBranch.Ambition, 3, "", "교주의 명령\u001FThe Leader's Command", "교주의 한마디는 설교보다 무겁고 더 존경받습니다.\u001FA single word from the leader weighs more and is more revered than a sermon.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 5f), Cult(StatId.LeaderFaith, -2f) }, GiftedSpecial.Chance("Preach", 6)),
        new("ambition04", DoctrineBranch.Ambition, 4, "", "감시의 눈\u001FWatchful Eyes", "측근들의 감시는 질서를 지키는 지혜로 칭송받습니다.\u001FYour inner circle's watch is praised as the wisdom that keeps order.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 4f), Cult(StatId.FollowerFaith, -2f) }, GiftedSpecial.Yearly(StatId.Authority, 10)),
        new("ambition05", DoctrineBranch.Ambition, 5, "", "절대 권위\u001FAbsolute Authority", "하늘에 닿는 교주의 권위를 모두가 우러러봅니다.\u001FAll look up to the leader's authority, which reaches the heavens.", 5, 0, new StatModifier[] { Cult(StatId.Authority, 4f), Cult(StatId.FollowerFaith, -1f) }, GiftedSpecial.Yearly(StatId.LeaderFaith, 3)),
        new("ambition06a", DoctrineBranch.Ambition, 6, "A", "정치 인맥\u001FPolitical Connections", "관청에 교단 사람을 심는 수완이 출세의 본보기가 됩니다.\u001FPlanting the cult's people in office becomes a model of success.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 7f), Cult(StatId.Authority, 5f), Cult(StatId.Doctrine, -3f) }),
        new("ambition06b", DoctrineBranch.Ambition, 6, "B", "교단 신문\u001FThe Cult Newspaper", "야망을 찬양하는 교단 신문이 거리마다 뿌려집니다.\u001FThe cult's newspaper, glorifying ambition, is handed out on every street.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 4f), Cult(StatId.Followers, 5f), Cult(StatId.FollowerFaith, -3f) }, GiftedSpecial.Chance("Proselytize", 3)),
        new("ambition07a", DoctrineBranch.Ambition, 7, "A", "충성 서약\u001FOath of Loyalty", "교주에게 바친 충성은 가장 빛나는 출세의 길입니다.\u001FLoyalty sworn to the leader is the brightest path to advancement.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 8f), Cult(StatId.Authority, 5f), Cult(StatId.LeaderFaith, -3f) }),
        new("ambition07b", DoctrineBranch.Ambition, 7, "B", "야심가 유지들\u001FAmbitious Notables", "지역의 야심가들이 교단 편에 서는 것을 자랑으로 삼습니다.\u001FThe region's ambitious notables take pride in siding with the cult.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 9f), Cult(StatId.FollowerFaith, -3f) }, GiftedSpecial.Yearly(StatId.Reputation, 6)),
        new("ambition08a", DoctrineBranch.Ambition, 8, "A", "교단 근위대\u001FThe Cult Guard", "교주를 지키는 근위대는 선망받는 영예의 자리입니다.\u001FThe guard protecting the leader is a coveted post of honor.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 6f), Cult(StatId.FollowerFaith, -5f) }, GiftedSpecial.Yearly(StatId.Authority, 20)),
        new("ambition08b", DoctrineBranch.Ambition, 8, "B", "의회 정복\u001FConquering Parliament", "교단 사람이 의회를 차지하자 모두가 박수를 보냅니다.\u001FA cult member seizes a seat in parliament to thunderous applause.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 8f), Cult(StatId.Offerings, 5f), Cult(StatId.Reputation, 3f), Cult(StatId.Doctrine, -4f) }),
        new("ambition09a", DoctrineBranch.Ambition, 9, "A", "신의 대리인\u001FGod's Proxy", "교주의 야망이 곧 신의 뜻이라 선포합니다.\u001FYou proclaim that the leader's ambition is God's will.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 9f), Cult(StatId.LeaderFaith, -5f) }, GiftedSpecial.Chance("Desire", 5), GiftedSpecial.Chance("Preach", 5)),
        new("ambition09b", DoctrineBranch.Ambition, 9, "B", "국교의 야망\u001FAmbition of a State Religion", "교단을 나라의 종교로 삼으려는 야망을 모두가 응원합니다.\u001FEveryone cheers your ambition to make the cult the nation's religion.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 11f), Cult(StatId.FollowerFaith, -4f) }, GiftedSpecial.Chance("Preach", 5)),
        new("ambition10a", DoctrineBranch.Ambition, 10, "A", "지상의 왕좌\u001FAn Earthly Throne", "교단은 이제 모두가 우러러보는 왕국입니다.\u001FThe cult is now a kingdom all look up to.", 2, 0, new StatModifier[] { Cult(StatId.Authority, 17f), Cult(StatId.Followers, 10f), Cult(StatId.Reputation, 6f), Cult(StatId.FollowerFaith, -6f) }, GiftedSpecial.Yearly(StatId.LeaderFaith, 4)),
        new("ambition10b", DoctrineBranch.Ambition, 10, "B", "신정 국가\u001FTheocracy", "교단의 법이 온 나라가 찬양하는 법이 되었습니다.\u001FThe cult's law has become the land's celebrated law.", 2, 0, new StatModifier[] { Cult(StatId.Authority, 13f), Cult(StatId.Reputation, 12f), Cult(StatId.Followers, 6f), Cult(StatId.LeaderFaith, -5f) }, GiftedSpecial.Yearly(StatId.LeaderFaith, 4)),
        new("temperance01", DoctrineBranch.Temperance, 1, "", "굶는 바보\u001FFool's Supper", "세상은 굶주린 식탁을 비웃지만, 교단은 적게 먹고 많이 기도합니다.\u001FThe world laughs at an empty plate, but the cult eats little and prays much.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Temperance, 5f), Cult(StatId.LeaderFaith, 4f), Cult(StatId.Reputation, -2f) }),
        new("temperance02", DoctrineBranch.Temperance, 2, "", "벙어리 수행\u001FMute Vow", "말 많은 세상이 벙어리라 놀려도, 침묵 속에서 신의 목소리를 듣습니다.\u001FThey call you mute, yet in silence you hear the voice of God.", 1, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 8f), Cult(StatId.Reputation, -2f) }),
        new("temperance03", DoctrineBranch.Temperance, 3, "", "어리석은 서원\u001FFoolish Vow", "모두가 미쳤다고 하는 금욕의 서원이 오히려 기도를 맑게 합니다.\u001FA vow of abstinence everyone calls madness clears the prayers instead.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Lust, -5f), Cult(StatId.Reputation, -2f) }, GiftedSpecial.Chance("CultPray", 6)),
        new("temperance04", DoctrineBranch.Temperance, 4, "", "메마른 몸\u001FBarren Body", "쾌락을 모르는 몸이라 조롱받지만, 불행도 그 몸에는 잘 달라붙지 못합니다.\u001FMocked as a body that knows no pleasure, yet misfortune struggles to cling to it.", 1, 5, new StatModifier[] { Personal(PersonalStatId.Health, 5f), Cult(StatId.Reputation, -2f) }),
        new("temperance05", DoctrineBranch.Temperance, 5, "", "멍한 명상\u001FIdle Meditation", "시간 낭비라 손가락질받는 명상이 깊어질수록 신앙은 단단해집니다.\u001FScorned as a waste of time, yet the deeper the meditation goes, the firmer the faith.", 5, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 2f), Personal(PersonalStatId.Piety, 1f) }, GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("temperance06a", DoctrineBranch.Temperance, 6, "A", "외딴 성소\u001FLonely Sanctuary", "아무도 찾지 않는 고요한 성소가 해마다 마음을 붙잡아 줍니다.\u001FEach year, the sanctuary no one visits steadies the heart.", 1, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 6f), Cult(StatId.Reputation, -3f) }, GiftedSpecial.Yearly(StatId.LeaderFaith, 12)),
        new("temperance06b", DoctrineBranch.Temperance, 6, "B", "괴짜 명상반\u001FOddballs' Class", "괴짜들의 모임이라 비웃어도, 누구나 와서 명상을 배울 수 있습니다.\u001FCall it a club for oddballs, but anyone can come and learn to meditate.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 4f), Cult(StatId.LeaderFaith, 4f), Cult(StatId.Reputation, -2f) }, GiftedSpecial.Chance("CultPray", 3)),
        new("temperance07a", DoctrineBranch.Temperance, 7, "A", "욕망 거부\u001FRefusing Desire", "세상이 권하는 욕망이 일어도, 고집스럽게 키우지 않습니다.\u001FEven when the desire the world urges on you stirs, you stubbornly refuse to feed it.", 1, 2, new StatModifier[] { Personal(PersonalStatId.Greed, -4f), Personal(PersonalStatId.Appetite, -4f), Personal(PersonalStatId.Lust, -4f), Cult(StatId.Reputation, -3f) }),
        new("temperance07b", DoctrineBranch.Temperance, 7, "B", "굶주림 수련회\u001FHunger Retreat", "미련하다는 소리를 들으며 굶을수록 기도는 깊어집니다.\u001FThe more you starve to cries of stupidity, the deeper the prayer.", 1, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 4f), Personal(PersonalStatId.Health, -3f), Cult(StatId.Reputation, -2f) }, GiftedSpecial.Chance("CultPray", 10)),
        new("temperance08a", DoctrineBranch.Temperance, 8, "A", "세상 밖 수도원\u001FHermits' Cloister", "세상에서 도망친 자들의 벽이라 불리지만, 그 벽이 불행을 막아 줍니다.\u001FCalled the walls of those who fled the world, they keep its misfortune out.", 1, 10, new StatModifier[] { Cult(StatId.FollowerFaith, 6f), Cult(StatId.Reputation, -3f) }),
        new("temperance08b", DoctrineBranch.Temperance, 8, "B", "바보의 고요서\u001FFool's Stillness", "아무도 사지 않을 명상의 가르침을 묵묵히 책으로 엮습니다.\u001FYou quietly bind the teachings of meditation into a book no one will buy.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 8f), Cult(StatId.LeaderFaith, 6f), Cult(StatId.Reputation, -3f) }),
        new("temperance09a", DoctrineBranch.Temperance, 9, "A", "빈털터리의 길\u001FPauper's Path", "세상이 가장 어리석다 여기는 일, 가진 모든 것을 내려놓습니다.\u001FYou do what the world thinks most foolish: let go of everything you own.", 1, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 14f), Cult(StatId.Offerings, -6f), Cult(StatId.Reputation, -4f) }, GiftedSpecial.FailHalf("CultPray")),
        new("temperance09b", DoctrineBranch.Temperance, 9, "B", "낙오자 수련원\u001FDropouts' Retreat", "낙오자들의 소굴이라 불리는 수련원에서 신도들은 해마다 마음을 다잡습니다.\u001FEach year, in a retreat called a den of dropouts, followers steady their hearts.", 1, 10, new StatModifier[] { Cult(StatId.Reputation, -4f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 12)),
        new("temperance10a", DoctrineBranch.Temperance, 10, "A", "해탈의 경지\u001FLiberation", "세상의 비웃음도 불행도 더는 교주의 마음을 흔들지 못합니다.\u001FNeither the world's ridicule nor misfortune can shake the cult leader's mind anymore.", 2, 14, new StatModifier[] { Cult(StatId.LeaderFaith, 12f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.FailHalf("All"), GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("temperance10b", DoctrineBranch.Temperance, 10, "B", "깨달음의 등불\u001FLamp of Enlightenment", "어둠 속 바보의 등불이라 비웃음을 받아도, 그 깨달음은 신도들의 길을 밝힙니다.\u001FMocked as a fool's lamp in the dark, your enlightenment still lights your followers' way.", 2, 10, new StatModifier[] { Cult(StatId.LeaderFaith, 10f), Cult(StatId.FollowerFaith, 11f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("charity01", DoctrineBranch.Charity, 1, "", "호구 이웃\u001FSoft Touch", "이웃을 공짜로 돕는 호구 교단이 있다는 소문이 퍼집니다.\u001FWord spreads of a soft-touch cult that helps its neighbors for nothing.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 6f), Cult(StatId.LeaderFaith, 2f), Cult(StatId.Reputation, -2f) }),
        new("charity02", DoctrineBranch.Charity, 2, "", "밑지는 급식\u001FLosing Meals", "손해만 보는 장사라 비웃어도 굶주린 이에게 음식을 나눕니다.\u001FThey call it a losing business, but you share food with the hungry.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, -2f) }, GiftedSpecial.Chance("Serve", 8)),
        new("charity03", DoctrineBranch.Charity, 3, "", "쓸모없는 간병\u001FWasted Care", "돈 안 되는 병자 곁에 머무는 어리석음을 고집합니다.\u001FYou stubbornly insist on the folly of staying by the sick, who bring no profit.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 7f), Personal(PersonalStatId.Health, 3f), Cult(StatId.Reputation, -2f) }),
        new("charity04", DoctrineBranch.Charity, 4, "", "밑 빠진 기금\u001FLeaky Fund", "밑 빠진 독이라 조롱받는 구호 기금이 해마다 이웃을 돕습니다.\u001FMocked as a bottomless pit, the relief fund helps your neighbors each year.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 5f), Cult(StatId.Offerings, -2f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 10)),
        new("charity05", DoctrineBranch.Charity, 5, "", "헤픈 손\u001FLoose Hand", "헤프다는 손가락질 속에서도 베풀수록 교단의 이름은 조용히 빛납니다.\u001FAmid jeers of wastefulness, the more you give, the more the cult's name quietly shines.", 5, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 4f), Cult(StatId.Offerings, -1f) }, GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("charity06a", DoctrineBranch.Charity, 6, "A", "버린 아이들의 집\u001FCastoffs' Home", "세상이 버린 쓸모없는 아이들을 교단이 거둡니다.\u001FThe cult takes in the children the world threw away as useless.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 4f), Personal(PersonalStatId.Charity, 5f), Cult(StatId.FollowerFaith, 3f), Cult(StatId.Reputation, -2f) }),
        new("charity06b", DoctrineBranch.Charity, 6, "B", "공짜 진료소\u001FFreeloaders' Clinic", "돈 없는 자도 치료받는, 세상이 비웃는 진료소를 엽니다.\u001FYou open a clinic the world mocks, where even the penniless are treated.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 5f), Personal(PersonalStatId.Health, 5f), Cult(StatId.Reputation, -2f) }),
        new("charity07a", DoctrineBranch.Charity, 7, "A", "바보 바자회\u001FFools' Bazaar", "이문 한 푼 안 남기는 바자회 수익이 전부 이웃에게 갑니다.\u001FNot a cent of profit is kept; every coin from the bazaar goes to the neighbors.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 3f), Cult(StatId.Offerings, -5f) }, GiftedSpecial.Chance("Serve", 11)),
        new("charity07b", DoctrineBranch.Charity, 7, "B", "헛된 야학\u001FFutile School", "배워 봤자 소용없다는 세상에서, 밤마다 배움에 목마른 이들을 가르칩니다.\u001FIn a world that says learning is useless, you teach the thirsty every night.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 7f), Personal(PersonalStatId.Mentality, 5f), Cult(StatId.Reputation, -3f) }),
        new("charity08a", DoctrineBranch.Charity, 8, "A", "물렁한 화해\u001FSpineless Peace", "줏대 없다는 소리를 들으며 다른 종교와도 손을 맞잡습니다.\u001FCalled spineless, you join hands even with other religions.", 1, 8, new StatModifier[] { Cult(StatId.Reputation, -3f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 12)),
        new("charity08b", DoctrineBranch.Charity, 8, "B", "적자 병원\u001FRed-Ink Hospital", "적자만 쌓이는 교단 병원이 해마다 이웃의 신뢰를 쌓습니다.\u001FThe hospital piles up only losses, yet each year it builds your neighbors' trust.", 1, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 8f), Cult(StatId.Reputation, -3f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 10), GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("charity09a", DoctrineBranch.Charity, 9, "A", "호구들의 집\u001FHouse of Suckers", "누구든 문을 두드리면 열어 주는, 세상이 호구라 부르는 집입니다.\u001FAnyone may knock on the door of the house the world calls a home for suckers.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 8f), Cult(StatId.FollowerFaith, 8f), Cult(StatId.Reputation, -4f) }),
        new("charity09b", DoctrineBranch.Charity, 9, "B", "돈 안 되는 학교\u001FUnprofitable School", "세상이 비웃는 교단의 학교에서 아이들이 자랍니다.\u001FChildren grow up in the cult's school, the one the world laughs at.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 5f), Cult(StatId.Doctrine, 5f), Cult(StatId.Reputation, -4f) }, GiftedSpecial.FailHalf("Serve")),
        new("charity10a", DoctrineBranch.Charity, 10, "A", "성인의 교단\u001FCult of Saints", "세상은 비웃듯 성인의 교단이라 부르지만, 교단은 그 이름을 기꺼이 짊어집니다.\u001FThe world sneers \"a cult of saints,\" and your cult gladly bears the name.", 2, 6, new StatModifier[] { Cult(StatId.FollowerFaith, 14f), Cult(StatId.LeaderFaith, 10f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("charity10b", DoctrineBranch.Charity, 10, "B", "치유의 성전\u001FTemple of Healing", "세상이 버린 병자들이 성전 밖에 길게 줄을 섭니다.\u001FThe sick the world cast aside line up in long queues outside the temple.", 2, 5, new StatModifier[] { Cult(StatId.Followers, 13f), Cult(StatId.FollowerFaith, 10f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.Yearly(PersonalStatId.Health, 2), GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("patience01", DoctrineBranch.Patience, 1, "", "미련한 마음\u001FDull Heart", "미련하다 비웃음을 받아도, 참는 법을 배운 신도는 쉽게 흔들리지 않습니다.\u001FMocked as dull, followers who learn to endure are not easily shaken.", 1, 4, new StatModifier[] { Personal(PersonalStatId.Patience, 5f), Cult(StatId.Reputation, -2f) }),
        new("patience02", DoctrineBranch.Patience, 2, "", "사서 고생\u001FAsking for Pain", "사서 고생한다고 비웃어도 실패한 기도마저 수행이 됩니다.\u001FThey say you ask for pain, yet even failed prayers become discipline.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, -2f) }, GiftedSpecial.FailHalf("CultPray")),
        new("patience03", DoctrineBranch.Patience, 3, "", "헛된 철야\u001FFutile Vigil", "잠을 버리는 바보짓이라 해도 밤샘 기도가 몸과 마음을 단련합니다.\u001FCalled a fool's waste of sleep, all-night prayer tempers body and mind.", 1, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 6f), Personal(PersonalStatId.Health, 4f), Cult(StatId.Reputation, -2f) }),
        new("patience04", DoctrineBranch.Patience, 4, "", "맞고 버티는 신도\u001FPunching Bags", "얻어맞고도 버티는 신도들이라 조롱받지만, 쉽게 꺾이지 않습니다.\u001FMocked as punching bags, your hardened followers do not easily break.", 1, 5, new StatModifier[] { Cult(StatId.FollowerFaith, 5f), Cult(StatId.Reputation, -2f) }),
        new("patience05", DoctrineBranch.Patience, 5, "", "고집 센 버팀목\u001FStubborn Pillar", "고집불통이라 불릴수록, 시련이 클수록 교단은 강해집니다.\u001FThe more they call you stubborn and the harder the trials, the stronger the cult.", 5, 3, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("patience06a", DoctrineBranch.Patience, 6, "A", "패배의 해석\u001FExcusing Defeat", "변명이라 비웃어도 실패한 설교와 포교마저 시련으로 받아들입니다.\u001FCall it excuses, but you accept even failed sermons and outreach as trials.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, -6f) }, GiftedSpecial.FailHalf("Preach"), GiftedSpecial.FailHalf("Proselytize")),
        new("patience06b", DoctrineBranch.Patience, 6, "B", "겁쟁이 서약\u001FCoward's Vow", "겁쟁이라 손가락질받아도 어떤 박해에도 손을 들지 않기로 맹세합니다.\u001FBranded cowards, you swear never to raise a hand, whatever the persecution.", 1, 8, new StatModifier[] { Cult(StatId.FollowerFaith, 4f), Cult(StatId.Reputation, -3f) }),
        new("patience07a", DoctrineBranch.Patience, 7, "A", "미련한 반석\u001FStubborn Rock", "미련한 돌덩이라 불리며 해마다 몸과 교단이 단단해집니다.\u001FCalled a dumb stone, yet each year your body and cult grow firmer.", 1, 7, new StatModifier[] { Cult(StatId.LeaderFaith, 3f), Cult(StatId.Reputation, -2f) }, GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("patience07b", DoctrineBranch.Patience, 7, "B", "바보들의 행진\u001FMarch of Fools", "비웃음 속 말없는 행렬이 끝내 사람들의 마음을 움직입니다.\u001FA wordless procession through the laughter moves people's hearts in the end.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 4f), Cult(StatId.Reputation, -3f) }, GiftedSpecial.Chance("Proselytize", 8)),
        new("patience08a", DoctrineBranch.Patience, 8, "A", "짓밟힌 자들\u001FThe Trampled", "짓밟히고도 버틴 이야기가 신도들의 가슴에 불을 지핍니다.\u001FTales of being trampled and enduring set your followers on fire.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 10f), Cult(StatId.LeaderFaith, 5f), Cult(StatId.Reputation, -4f) }),
        new("patience08b", DoctrineBranch.Patience, 8, "B", "옥중 서신\u001FLetters from Prison", "어리석게 갇힌 교주의 옥중 편지가 신도들을 일으킵니다.\u001FLetters from the foolishly jailed cult leader rally the followers.", 1, 6, new StatModifier[] { Cult(StatId.FollowerFaith, 8f), Cult(StatId.Reputation, -2f) }),
        new("patience09a", DoctrineBranch.Patience, 9, "A", "끝없는 인내\u001FEndless Patience", "세상이 질려 할 만큼 참고 또 참아, 모든 실패가 절반만 아픕니다.\u001FYou endure until the world grows weary of you, and every failure hurts only half as much.", 1, 8, new StatModifier[] { Cult(StatId.Reputation, -4f) }, GiftedSpecial.FailHalf("All")),
        new("patience09b", DoctrineBranch.Patience, 9, "B", "패배자의 기록\u001FLosers' Chronicle", "패배자의 넋두리라 불리는 박해의 기록이 세상의 양심을 깨웁니다.\u001FDismissed as losers' whining, the record of persecution awakens the world's conscience.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.FollowerFaith, 12), GiftedSpecial.FailHalf("Serve"), GiftedSpecial.Yearly(StatId.Reputation, -2)),
        new("patience10a", DoctrineBranch.Patience, 10, "A", "순교자의 교단\u001FCult of Martyrs", "바보들의 교단이라 비웃음을 받아도, 불행이 닥쳐도 교단은 쓰러지지 않습니다.\u001FMocked as a cult of fools, your cult still does not fall when misfortune strikes.", 2, 19, new StatModifier[] { Cult(StatId.FollowerFaith, 10f), Cult(StatId.LeaderFaith, 5f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("patience10b", DoctrineBranch.Patience, 10, "B", "불굴의 행렬\u001FUnbreakable Procession", "비웃던 세상도 굽히지 않는 행렬 앞에서는 길을 비킵니다.\u001FEven the mocking world parts before a procession that will not bend.", 2, 14, new StatModifier[] { Cult(StatId.FollowerFaith, 12f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.FailHalf("Proselytize"), GiftedSpecial.Yearly(StatId.Reputation, 3)),
        new("integrity01", DoctrineBranch.Integrity, 1, "", "순진한 장부\u001FNaive Ledger", "요령 없는 바보처럼 장부에 아무것도 숨기지 않습니다.\u001FLike a fool with no sense, you hide nothing in the books.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Integrity, 5f), Cult(StatId.Doctrine, 3f), Cult(StatId.Reputation, -2f) }),
        new("integrity02", DoctrineBranch.Integrity, 2, "", "바보 헌금함\u001FFools' Offering Box", "떼먹을 줄도 모른다고 비웃음을 받아도 헌금이 어디 쓰이는지 모두가 압니다.\u001FThey mock you for not knowing how to skim, yet everyone knows where the Offerings go.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 3f), Cult(StatId.FollowerFaith, 5f), Cult(StatId.Reputation, -2f) }),
        new("integrity03", DoctrineBranch.Integrity, 3, "", "눈치 없는 설교\u001FTactless Sermon", "듣기 좋은 거짓 하나 없는 눈치 없는 설교가 오히려 마음에 닿습니다.\u001FA tactless sermon without a single sweet lie reaches the heart instead.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 5f), Cult(StatId.Reputation, -2f) }, GiftedSpecial.Chance("Preach", 5)),
        new("integrity04", DoctrineBranch.Integrity, 4, "", "쓸데없는 연구\u001FPointless Study", "돈 안 되는 짓이라 해도 교리를 다듬고 또 다듬습니다.\u001FThough they call it pointless, you refine the Doctrine again and again.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 9f), Cult(StatId.Reputation, -2f) }),
        new("integrity05", DoctrineBranch.Integrity, 5, "", "순진한 이름\u001FNaive Name", "순진하다는 비웃음 속에서도 정직이 쌓일수록 이름은 깨끗해집니다.\u001FAmid laughter at your naivety, the more honesty builds, the cleaner your name.", 5, 0, new StatModifier[] { Cult(StatId.Doctrine, 4f), Cult(StatId.Reputation, -1f) }, GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("integrity06a", DoctrineBranch.Integrity, 6, "A", "바보 회계\u001FFool's Accounts", "세상은 손해라 비웃지만, 해마다 회계를 공개해 신뢰를 얻습니다.\u001FThe world calls it a loss, but each year you publish your accounts and earn trust.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 7f), Cult(StatId.Reputation, -3f) }, GiftedSpecial.Yearly(StatId.FollowerFaith, 10)),
        new("integrity06b", DoctrineBranch.Integrity, 6, "B", "고지식 학교\u001FSchool of Prigs", "고지식하다 놀림받는, 교리를 법처럼 가르치는 학교를 엽니다.\u001FYou open a school mocked as priggish that teaches Doctrine like law.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 8f), Cult(StatId.Authority, 3f), Cult(StatId.Reputation, -2f) }),
        new("integrity07a", DoctrineBranch.Integrity, 7, "A", "아무도 안 읽는 경전\u001FUnread Scripture", "아무도 읽지 않을 거라 비웃는 경전을 펴내 교리를 정리합니다.\u001FYou publish a scripture they say no one will read, setting the Doctrine in order.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 9f), Cult(StatId.Reputation, -3f) }, GiftedSpecial.Yearly(StatId.Doctrine, 10)),
        new("integrity07b", DoctrineBranch.Integrity, 7, "B", "꽉 막힌 법정\u001FRigid Tribunal", "융통성 없다 불리는 교단 법정이 교단 안의 분쟁을 가립니다.\u001FThe tribunal called rigid settles disputes within the cult.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 7f), Cult(StatId.Reputation, -3f) }, GiftedSpecial.Chance("Preach", 5)),
        new("integrity08a", DoctrineBranch.Integrity, 8, "A", "융통성 없는 판결\u001FInflexible Verdict", "뇌물 하나 안 통한다고 비웃음을 받아도 공정한 판결이 교단을 지킵니다.\u001FThey mock you because no bribe works, yet fair verdicts protect the cult.", 1, 6, new StatModifier[] { Cult(StatId.Authority, 5f), Cult(StatId.LeaderFaith, 5f), Cult(StatId.Reputation, -3f) }),
        new("integrity08b", DoctrineBranch.Integrity, 8, "B", "족쇄 율법\u001FShackle Law", "스스로 족쇄를 찬다고 비웃어도 율법을 글로 새겨 모두가 지키게 합니다.\u001FThey laugh that you shackle yourselves, but you carve the law into writing for all to keep.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 10f), Cult(StatId.FollowerFaith, 4f), Cult(StatId.Reputation, -3f) }),
        new("integrity09a", DoctrineBranch.Integrity, 9, "A", "제 살 깎기\u001FCutting Own Flesh", "남들은 다 하는 부패를 제 살 깎듯 뿌리째 뽑아냅니다.\u001FLike cutting your own flesh, you root out the corruption everyone else enjoys.", 1, 4, new StatModifier[] { Cult(StatId.LeaderFaith, 8f), Personal(PersonalStatId.Greed, -6f), Cult(StatId.Reputation, -6f) }),
        new("integrity09b", DoctrineBranch.Integrity, 9, "B", "꼿꼿한 재판관\u001FUnbending Judge", "세상이 답답해할 만큼 공정한 재판이 해마다 교리를 다듬습니다.\u001FTrials fair enough to frustrate the world refine the Doctrine each year.", 1, 11, new StatModifier[] { Cult(StatId.Reputation, -4f) }, GiftedSpecial.Yearly(StatId.Doctrine, 10)),
        new("integrity10a", DoctrineBranch.Integrity, 10, "A", "빛의 교단\u001FCult of Light", "바보처럼 다 드러낸 교단에는 빛 아래 숨길 것이 남지 않았습니다.\u001FHaving foolishly bared everything, your cult has nothing left to hide in the light.", 2, 10, new StatModifier[] { Cult(StatId.Doctrine, 13f), Cult(StatId.LeaderFaith, 11f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.Yearly(StatId.Reputation, 2)),
        new("integrity10b", DoctrineBranch.Integrity, 10, "B", "율법의 수호자\u001FGuardian of the Law", "모두가 법을 비웃는 세상에서 교단은 흔들리지 않는 율법 위에 섭니다.\u001FIn a world that laughs at law, the cult stands on an unshakable law.", 2, 10, new StatModifier[] { Cult(StatId.Doctrine, 15f), Cult(StatId.Authority, 9f), Cult(StatId.Reputation, -6f) }, GiftedSpecial.Yearly(StatId.Reputation, 3)),
    };

    public static DoctrineSkill Find(string id) => id == DoctrineSkill.DeclarationId ? DoctrineSkill.Declaration : All.FirstOrDefault(s => s.Id == id);

    // 6~10단계는 갈래(A/B)를 지정한다
    public static DoctrineSkill At(DoctrineBranch branch, int tier, string path = "") => All.FirstOrDefault(s => s.Branch == branch && s.Tier == tier && s.Path == (tier <= 5 ? "" : path));
}
